"""Turn the backtest's results into the site's trader-skill page (experiments/trader_skill/index.html).

    python page.py --results results --out ../../experiments/trader_skill/index.html

results is the folder run.py backtest wrote (results.json, copycat_equity.csv, congress_equity.csv), or the files from the
"trader-skill-results" release. The page is static: the backtest is a one-off study, so the page is regenerated by hand
when the study is rerun. Standard library + pandas.
"""

from __future__ import annotations

import argparse
import html
import json
from pathlib import Path

import pandas as pd

e = html.escape
DARK = "--bg:#121416;--paper:#1a1d20;--ink:#e6e8e9;--muted:#9aa3a8;--rule:#2d3236;--pos:#6cc591;--neg:#ec8076;--c1:#e3ac5b;--c2:#7fb0e6;--c3:#bb93d8;color-scheme:dark"
COLORS = ["var(--c1)", "var(--c2)", "var(--c3)", "var(--muted)"]


def pct(x, sign: bool = True) -> str:
    if x is None:
        return "–"
    return f"{100 * x:+.1f}%" if sign else f"{100 * x:.1f}%"


def cls(x) -> str:
    return "" if x is None else ("pos" if x > 0 else "neg" if x < 0 else "")


def chart(df: pd.DataFrame, series: list[tuple[str, str]], start: str, title: str) -> str:
    """Inline SVG of growth of 1 from `start`, weekly points, one line per (column, label)."""
    d = df.loc[df.index >= start, [c for c, _ in series]].resample("W-FRI").last().dropna(how="all").ffill()
    d = d / d.iloc[0]
    w, h, pl, pr, pt, pb = 760, 300, 46, 120, 12, 26
    lo, hi = float(d.min().min()), float(d.max().max())
    x = lambda i: pl + (w - pl - pr) * i / max(len(d) - 1, 1)  # noqa: E731
    y = lambda v: pt + (h - pt - pb) * (1 - (v - lo) / (hi - lo or 1))  # noqa: E731
    out = [f'<figure><figcaption>{e(title)}</figcaption><svg viewBox="0 0 {w} {h}" role="img" aria-label="{e(title)}">']
    for k in range(5):
        v = lo + (hi - lo) * k / 4
        out.append(f'<line class="grid" x1="{pl}" x2="{w - pr}" y1="{y(v):.1f}" y2="{y(v):.1f}"/>'
                   f'<text class="ax" x="{pl - 6}" y="{y(v) + 4:.1f}" text-anchor="end">{v:.1f}x</text>')
    for yr in sorted({t.year for t in d.index})[1::2]:
        i = d.index.searchsorted(pd.Timestamp(f"{yr}-01-01"))
        if 0 < i < len(d):
            out.append(f'<text class="ax" x="{x(i):.1f}" y="{h - 6}" text-anchor="middle">{yr}</text>')
    for k, (col, label) in enumerate(series):
        pts = " ".join(f"{x(i):.1f},{y(v):.1f}" for i, v in enumerate(d[col]))
        c = "var(--muted)" if col == "SPY" else COLORS[k % len(COLORS)]
        last = float(d[col].iloc[-1])
        out.append(f'<polyline fill="none" stroke="{c}" stroke-width="{1.5 if col == "SPY" else 2}" points="{pts}"/>'
                   f'<text class="lab" x="{w - pr + 6}" y="{y(last) + 4:.1f}" fill="{c}">{e(label)} {last:.1f}x</text>')
    return "".join(out) + "</svg></figure>"


def build(results: Path) -> str:
    r = json.loads((results / "results.json").read_text())
    cc, cg = r["copycat"], r["congress"]
    filers = sorted((f for f in cc["filers"].values() if "cagr" in f.get("top10_filed", {})), key=lambda f: -f["top10_filed"]["excess_cagr"])
    rows = "".join(
        f'<tr><td>{e(f["name"].title() if f["name"].isupper() else f["name"])}</td><td class="mono">{f["quarters"]}</td>'
        f'<td class="mono">{pct(f["top10_filed"]["cagr"])}</td><td class="mono {cls(f["top10_filed"]["excess_cagr"])}">{pct(f["top10_filed"]["excess_cagr"])}</td>'
        f'<td class="mono">{f["top10_filed"]["sharpe"]}</td><td class="mono">{f["top10_filed"]["alpha_t"]}</td>'
        f'<td class="mono {cls(f["top10_period"].get("excess_cagr"))}">{pct(f["top10_period"].get("excess_cagr"))}</td></tr>' for f in filers)
    allf = cc["all_filers_equal_weight"]["top10_filed"]
    groups = [("all_buys", "Every House stock buy"), ("big_buys_50k_plus", "Buys of $50k or more"), ("pelosi_buys", "Pelosi's buys"), ("all_sells", "Every sale (should fall if informative)")]
    ev = ""
    for k, label in groups:
        x = cg[k]["events_filed"]
        cells = "".join(f'<td class="mono {cls(x.get(h, {}).get("mean"))}">{pct(x.get(h, {}).get("mean"))}</td>' for h in ("21d", "63d", "126d", "252d"))
        ev += f'<tr><td>{e(label)}</td><td class="mono">{x["n"]:,}</td>{cells}</tr>'
    pf = ""
    for k, label in groups[:3]:
        s = cg[k]["portfolio_filed"]
        pf += (f'<tr><td>{e(label)}</td><td class="mono">{pct(s["cagr"])}</td><td class="mono">{pct(s["spy_cagr"])}</td>'
               f'<td class="mono {cls(s["alpha"])}">{pct(s["alpha"])}</td><td class="mono">{s["alpha_t"]}</td><td class="mono">{s["sharpe"]}</td>'
               f'<td class="mono">{pct(s["max_dd"])}</td></tr>')
    cov = cg["coverage"]
    cop = pd.read_csv(results / "copycat_equity.csv", index_col=0, parse_dates=True)
    con = pd.read_csv(results / "congress_equity.csv", index_col=0, parse_dates=True)
    brk = next(c for c in cop.columns if c.startswith("BERKSHIRE") and c.endswith("|top10_filed"))
    ch1 = chart(cop, [("ALL|top10_filed", "23 funds"), (brk, "Berkshire"), ("SPY", "SPY")], "2014-01-01",
                "Copying 13F top 10s, growth of 1 since 2014 (bought the day after each filing)")
    ch2 = chart(con, [("pelosi_buys|filed", "Pelosi"), ("big_buys_50k_plus|filed", "$50k+ buys"), ("all_buys|filed", "All buys"), ("SPY", "SPY")],
                "2019-07-15", "Copying House buys, growth of 1 since mid 2019 (bought the day after disclosure)")
    pel, allb = cg["pelosi_buys"]["portfolio_filed"], cg["all_buys"]["portfolio_filed"]
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow">
<title>trader-skill test</title><style>
:root{{--bg:#f6f5f1;--paper:#fff;--ink:#1d2124;--muted:#5f676c;--rule:#dcdad3;--pos:#2c7a4b;--neg:#b4443a;--c1:#b5761f;--c2:#2f6fae;--c3:#7a4f9a;
--sans:system-ui,-apple-system,"Segoe UI",sans-serif;--mono:ui-monospace,Menlo,Consolas,monospace}}
@media (prefers-color-scheme:dark){{:root:not([data-theme="light"]){{{DARK}}}}}
:root[data-theme="dark"]{{{DARK}}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 var(--sans)}}
.wrap{{max-width:960px;margin:0 auto;padding:28px 16px 64px}}h1{{font-size:clamp(1.6rem,4vw,2.3rem);margin:0 0 6px}}
h2{{font-size:1.2rem;margin:34px 0 10px;padding-top:12px;border-top:2px solid var(--ink)}}p{{max-width:72ch;margin:0 0 12px}}
.lede{{color:var(--muted);font-size:1.08rem}}.mono{{font-family:var(--mono);font-size:.88em}}.muted{{color:var(--muted)}}.small{{font-size:.88rem}}
.verdict{{background:var(--paper);border:1px solid var(--rule);border-left:4px solid var(--c1);padding:14px 16px;margin:18px 0}}
.stats{{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px;margin:14px 0}}
.stat{{background:var(--paper);border:1px solid var(--rule);padding:12px}}.stat b{{display:block;font:600 1.4rem var(--mono)}}.stat span{{color:var(--muted);font-size:.85rem}}
.tbl{{overflow-x:auto;background:var(--paper);border:1px solid var(--rule)}}table{{border-collapse:collapse;width:100%;font-size:.92rem}}
th,td{{padding:7px 10px;border-bottom:1px solid var(--rule);text-align:right;white-space:nowrap}}th:first-child,td:first-child{{text-align:left}}
th{{font-weight:600;color:var(--muted);font-size:.8rem}}.pos{{color:var(--pos)}}.neg{{color:var(--neg)}}
figure{{margin:16px 0;background:var(--paper);border:1px solid var(--rule);padding:12px}}figcaption{{font-size:.9rem;color:var(--muted);margin-bottom:6px}}
svg{{width:100%;height:auto;display:block}}.grid{{stroke:var(--rule)}}.ax{{fill:var(--muted);font:11px var(--mono)}}.lab{{font:600 12px var(--sans)}}
a{{color:var(--c2)}}</style></head><body><main class="wrap">
<h1>trader-skill, tested</h1>
<p class="lede">Can you beat the market by copying famous investors or members of Congress? A backtest of the two signals in
<a href="https://github.com/Jakeschincariol/trader-skill">Jake Schincariol's trader-skill</a> Claude skills, using its own SEC and House readers.</p>
<div class="verdict"><b>Verdict: no tested edge.</b> Copying 23 famous funds' 13F filings matched SPY, and copying every stock buy the House
discloses trailed it. Pelosi's own buys are the one outlier, carried by a few big tech positions. The repo is genuine and safe
(public data only, never places orders); the rest of it is tools for running a real brokerage account, which this paper-only project does not need.</div>
<div class="stats">
<div class="stat"><span>23 funds' top 10, copied</span><b class="{cls(allf['excess_cagr'])}">{pct(allf['excess_cagr'])}/yr</b><span>vs SPY, {allf['start'][:4]} to {allf['end'][:4]}</span></div>
<div class="stat"><span>Every House stock buy, copied</span><b class="{cls(allb['alpha'])}">{pct(allb['cagr'] - allb['spy_cagr'])}/yr</b><span>vs SPY, {cov['buys_priced']:,} buys since 2019</span></div>
<div class="stat"><span>Pelosi's buys, copied</span><b class="pos">{pct(pel['cagr'] - pel['spy_cagr'])}/yr</b><span>vs SPY, 60 buys, alpha t {pel['alpha_t']}</span></div>
</div>
<h2>Copying famous investors (13F)</h2>
<p>Funds over $100M file their US stock holdings every quarter, up to 45 days after it ends. The copy buys each fund's 10
biggest stock positions (weighted by value) the trading day after the filing appears, holds until the next one, and pays 5 bp a side.
The last column enters at the quarter end instead, which nobody could do: the gap is what the delay costs.</p>
{ch1}
<div class="tbl"><table><tr><th>Fund</th><th>Quarters</th><th>CAGR</th><th>vs SPY</th><th>Sharpe</th><th>Alpha t</th><th>Hindsight vs SPY</th></tr>{rows}</table></div>
<p class="small muted">All 23 equal weight: CAGR {pct(allf['cagr'])} vs SPY {pct(allf['spy_cagr'])}, Sharpe {allf['sharpe']} vs {allf['spy_sharpe']},
alpha {pct(allf['alpha'])} (t {allf['alpha_t']}). Ranking 23 funds after the fact always produces winners: a t below about 3 is not
convincing here. Funds are the ones the skill lists.</p>
<h2>Copying Congress (House trade disclosures)</h2>
<p>Members of the House report their stock trades within 30 to 45 days (median here: {cov['median_disclosure_lag_days']} days). The test reads
{cov['ptr_filings']:,} reports from 2019 on ({cov['scanned_paper']:,} scanned paper forms could not be read) and buys each disclosed purchase the day after it is published.</p>
{ch2}
<p class="small muted">Average return above SPY after the disclosure:</p>
<div class="tbl"><table><tr><th>Group</th><th>Trades</th><th>1 month</th><th>3 months</th><th>6 months</th><th>1 year</th></tr>{ev}</table></div>
<p class="small muted">As portfolios, each buy held about 6 months, equal weight, 5 bp a side:</p>
<div class="tbl"><table><tr><th>Group</th><th>CAGR</th><th>SPY</th><th>Alpha</th><th>Alpha t</th><th>Sharpe</th><th>Max drawdown</th></tr>{pf}</table></div>
<h2>What to keep in mind</h2>
<p>Prices come from Yahoo, which has no delisted stocks, so both tests flatter the strategies a little. Pelosi's numbers rest on one
person and about 60 trades, mostly a few large tech positions held a year; she often buys call options, and the test copies with shares.
Her disclosed buys are already traded on paper as the Pelosi pot on the Markets page.</p>
<p class="small muted">Generated {e(r['generated'][:10])} from trader-skill commit {e(r['skill_commit'][:7])}. Code: research/trader_skill in the repository.</p>
</main></body></html>"""


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--results", type=Path, default=Path("results"))
    ap.add_argument("--out", type=Path, required=True)
    a = ap.parse_args()
    a.out.parent.mkdir(parents=True, exist_ok=True)
    a.out.write_text(build(a.results), encoding="utf-8")


if __name__ == "__main__":
    main()
